# ---------------------------------------------------------------- 1. the bubble
# B0(s, m, m) with m = 1: real part, and the imaginary part that switches on at s = 4 m^2.
s = var('s')
# finite_part(expr, mu_value): the second argument is the VALUE of mu, not an order.
Bfin = finite_part(B0(s, _sage_const_1 , _sage_const_1 ), _sage_const_1 )          # = DiscB(s,1,1) + 2
from sage.all import pi as PI, sqrt as SQRT, RR

def val(x, part):
    try:
        z = CC(Bfin.subs({s: x}))
    except Exception:
        return float('nan')
    return float(z.real()) if part == 're' else float(z.imag())

def im_exact(x):
    return float(RR(PI*SQRT(_sage_const_1  - _sage_const_4 /x))) if x > _sage_const_4  else _sage_const_0p0 

fig = curves([lambda x: val(x, 're'), lambda x: val(x, 'im'), im_exact], (-_sage_const_4 , _sage_const_16 ),
             labels=[r'$\mathrm{Re}\,B_0$', r'$\mathrm{Im}\,B_0$',
                     r'$\pi\sqrt{1-4m^2/s}$'],
             xlabel=r'$s/m^2$', title=r'$B_0(s;m,m)$, finite part, $m=\mu=1$',
             figsize=(_sage_const_5p2 , _sage_const_3p1 ))
